#include <iostream>
using namespace std;

int main() {
    int n, chest = 0, biceps = 0, back = 0;
    cin >> n;

    for (int i = 0, exercise; i < n; ++i) {
        cin >> exercise;
        if (i % 3 == 0) chest += exercise;
        else if (i % 3 == 1) biceps += exercise;
        else back += exercise;
    }

    if (chest > biceps && chest > back)
        cout << "chest";
    else if (biceps > chest && biceps > back)
        cout << "biceps";
    else
        cout << "back";

    return 0;
}

